def _upload_video(self):
    """Sube UN video como contenido de un modulo -> assets/_modulos/<key>.mp4|.webm
       (crudo, sin recomprimir: no hay ffmpeg y el panel es stdlib+Pillow)."""
    ctype = self.headers.get("Content-Type", "")
