/* ===================================================================
   VIDEO: archivo MP4 subido al proyecto, o link externo (YouTube/Vimeo/Drive)
   =================================================================== */
const VIDEO_MAX_MB = 20;   // espejo de VIDEO_MAX_MB en panel_server.py (ver justificacion alli)
const VIDEO_RATIOS = { vertical: 0.5625, cuadrado: 1, horizontal: 1.7778 };

// ancho/alto que usa la caja del video. Si el panel midio el archivo, va el ratio
// REAL (=> cero franjas negras); si no (modo link), el nominal de la orientacion.
function vidRatio(bk) {
  const r = parseFloat(bk.ratio);
  if (r > 0.05 && r < 20) return r.toFixed(4);
  return String(VIDEO_RATIOS[bk.orient] || VIDEO_RATIOS.horizontal);
}
function esArchivoUrl(u) { return /\.(mp4|webm)(\?|#|$)/i.test(u || ''); }

// normaliza el link pegado a una URL EMBEBIBLE (si no la reconoce, la deja igual)
function embedVideoUrl(u) {
  u = (u || '').trim();
  let m;
  if ((m = u.match(/(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|embed\/|live\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/)))
    return 'https://www.youtube-nocookie.com/embed/' + m[1] + '?rel=0&playsinline=1';
  if ((m = u.match(/vimeo\.com\/(?:video\/)?(\d+)/)))
    return 'https://player.vimeo.com/video/' + m[1];
  if ((m = u.match(/drive\.google\.com\/file\/d\/([A-Za-z0-9_-]+)/)))
    return 'https://drive.google.com/file/d/' + m[1] + '/preview';
  return u;
}

// atributos del <video> publicado
function vidAttrs(bk) {
  const a = ['playsinline', 'preload="metadata"'];
  if (bk.controles !== false) a.push('controls');
  if (bk.autoplay) a.push('autoplay', 'muted');      // sin muted el navegador BLOQUEA el autoplay
  else if (bk.silenciado) a.push('muted');
  if (bk.loop) a.push('loop');
  if (!bk.descargable) a.push('controlsList="nodownload"');
  return ' ' + a.join(' ');
}

