// mide el video EN EL CLIENTE con un <video> temporal (nunca lo reproduce).
// Asi el bloque guarda la orientacion y el ratio reales, y la intranet no tiene
// que esperar la metadata para armar la caja. Devuelve {w,h,ratio,dur} o null.
function medirVideo(file) {
  return new Promise(resolve => {
    let listo = false;
    const url = URL.createObjectURL(file);
    const v = document.createElement('video');
    v.preload = 'metadata'; v.muted = true; v.playsInline = true;
    const fin = r => {
      if (listo) return; listo = true;
      try { URL.revokeObjectURL(url); } catch (e) {}
      v.removeAttribute('src');
      resolve(r);
    };
    v.onloadedmetadata = () => {
      const w = v.videoWidth | 0, h = v.videoHeight | 0, d = v.duration;
      fin(w && h ? { w, h, ratio: +(w / h).toFixed(4), dur: (isFinite(d) ? Math.round(d) : 0) } : null);
    };
    v.onerror = () => fin(null);
    setTimeout(() => fin(null), 8000);   // codec raro: no bloquear la subida por esto
    v.src = url;
  });
}

async function subirVideoBloque(bk, file) {
  const mb = file.size / 1048576;
  if (mb > VIDEO_MAX_MB) {
    toast('El video pesa ' + mb.toFixed(1) + ' MB y el tope es ' + VIDEO_MAX_MB + ' MB. Comprimilo a 720p, o subilo a YouTube/Drive y usá la opción Link.', 'err');
    return;
  }
  // 1) medir ANTES de subir (rapido: solo lee la metadata del archivo local)
  const meta = await medirVideo(file);
  // 2) subir
  const fd = new FormData();
  fd.append('key', (det.key || $('#dTitle').value || 'modulo') + '-vid-' + Date.now());
  fd.append('file', file);
  if (bk.src) fd.append('previo', bk.src);   // borra el que reemplaza: no deja 20 MB huerfanos
  toast('Subiendo video (' + mb.toFixed(1) + ' MB)… puede tardar unos segundos.');
  try {
    const r = await api('/api/upload-video', { method: 'POST', body: fd });
    bk.modo = 'archivo';
    bk.src = r.src;
    bk.mb = +mb.toFixed(1);
    if (meta) {
      bk.w = meta.w; bk.h = meta.h; bk.dur = meta.dur; bk.ratio = meta.ratio;
      bk.orient = meta.ratio < 0.95 ? 'vertical' : (meta.ratio > 1.05 ? 'horizontal' : 'cuadrado');
    }
    if (!bk.titulo) bk.titulo = file.name.replace(/\.[^.]+$/, '');
    renderCanvas(); renderInspector();
    toast(meta ? ('Video listo · ' + meta.w + '×' + meta.h + ' (' + bk.orient + ')') : 'Video listo', 'ok');
  } catch (e) { toast(e.message, 'err'); }
}

