/* ============ BLOQUE VIDEO ============
   (a) ORIENTACION AUTOMATICA. El panel puede no saber si el archivo que
       subieron es vertical u horizontal. Apenas el navegador lee el header del
       archivo (por eso preload="metadata") le ponemos a la caja la proporcion
       REAL: sirve para 9:16, 16:9 y tambien para rarezas tipo 4:5 o 1:1.
       OJO: los eventos de media NO burbujean -> hay que escuchar en CAPTURA
       (tercer argumento true). Asi un solo listener cubre los tres lugares
       donde se reemplaza innerHTML (renderSection, verDoc pagina y verDoc deck)
       sin tener que engancharse en cada uno.
       Los estilos inline le ganan a las clases, asi que la medida real siempre
       pisa al 9/16 o 16/9 que puso el panel. */
document.addEventListener('loadedmetadata', function(e){
  const v = e.target;
  if(!v || v.tagName !== 'VIDEO' || !v.videoWidth || !v.videoHeight) return;
  const cont = v.closest && v.closest('.m-video');
  if(!cont) return;
  cont.style.setProperty('--arw', v.videoWidth);
  cont.style.setProperty('--arh', v.videoHeight);
  const vertical = v.videoHeight > v.videoWidth;
  cont.classList.toggle('vert',  vertical);   /* .vert tambien sube el --vmax */
  cont.classList.toggle('horiz', !vertical);
}, true);

/* (b) "VER EN GRANDE". Tres caminos, en este orden:
     1. iPhone: Element.requestFullscreen NO existe en Safari de iPhone (si en
        iPadOS 13+). Lo unico que hay es webkitEnterFullscreen(), que existe
        SOLO sobre el <video>, exige metadata cargada (readyState>=1) y gesto
        del usuario. Abre el reproductor nativo (scrubber, AirPlay, rotacion).
     2. Resto: requestFullscreen() sobre el <video> (o sobre la caja, si es un
        embed de YouTube/Vimeo: ahi no tenemos acceso al <video> por ser
        cross-origin y el fullscreen lo maneja el propio iframe).
     3. Si no hay ninguno de los dos: overlay propio #vidview.
   Nota: con playsinline los controles nativos YA traen su boton de expandir;
   este boton grande es para que el vendedor lo encuentre sin buscarlo. */
function verVideoGrande(btn){
  const cont = btn.closest('.m-video'); if(!cont) return;
  const v = cont.querySelector('video');
  if(!v){                                   /* embed externo (iframe) */
    const f = cont.querySelector('iframe');
    const box = cont.querySelector('.v-box') || f;
    const rq = box && (box.requestFullscreen || box.webkitRequestFullscreen);
    if(rq){ try{ Promise.resolve(rq.call(box)).catch(()=>{}); }catch(err){} }
    return;
  }
  /* iPhone (no hay fullscreen de elementos, si de video) */
  if(typeof v.webkitEnterFullscreen === 'function' && !document.fullscreenEnabled){
    try{
      if(v.readyState >= 1){ v.webkitEnterFullscreen(); v.play().catch(()=>{}); return; }
    }catch(err){}
    /* sin metadata todavia: iOS puede rechazarlo por perder el gesto del
       usuario, asi que ahi caemos al overlay en vez de no hacer nada */
    return abrirVideoOverlay(v);
  }
  const rq = v.requestFullscreen || v.webkitRequestFullscreen;
  if(rq){ try{ Promise.resolve(rq.call(v)).catch(()=>abrirVideoOverlay(v)); }catch(err){ abrirVideoOverlay(v); } v.play().catch(()=>{}); }
  else abrirVideoOverlay(v);
}

/* (c) overlay propio: ultimo recurso. Mismo patron que openPdf(). */
function abrirVideoOverlay(v){
  const src = (v.currentSrc || v.getAttribute('src') || '');
  if(!src) return;
  const t = v.currentTime || 0;
  v.pause();
  let ov = document.getElementById('vidview');
  if(!ov){ ov=document.createElement('div'); ov.id='vidview'; ov.onclick=e=>{ if(e.target===ov) cerrarVideo(); }; document.body.appendChild(ov); }
  ov.innerHTML = `<button class="vv-x" aria-label="Cerrar" onclick="cerrarVideo()">${svg(I.x)}</button>`
    + `<video id="vvPlay" src="${esc(src)}" controls playsinline preload="metadata" onclick="event.stopPropagation()"></video>`;
  ov.hidden=false; document.body.style.overflow='hidden';
  const p = document.getElementById('vvPlay');
  /* currentTime antes de tener metadata se ignora o tira error: hay que esperar */
  p.addEventListener('loadedmetadata', ()=>{ try{ p.currentTime = t; }catch(err){} p.play().catch(()=>{}); }, {once:true});
}
function cerrarVideo(){
  const ov=document.getElementById('vidview');
  if(ov){ const p=ov.querySelector('video'); if(p) p.pause(); ov.hidden=true; ov.innerHTML=''; }
  document.body.style.overflow='';
}

/* Convierte un link normal de YouTube / Vimeo / Drive en la URL EMBEBIBLE.
   La URL de salida se ARMA con el ID extraido, nunca se reusa la URL cruda:
   asi un link raro (javascript:, otro dominio, parametros inyectados) no puede
   colarse dentro del iframe que despues queda guardado como HTML en modulos.js.
   Devuelve null si no reconoce el servicio -> ahi el bloque muestra un boton
   "Abrir el video" en vez de un iframe (muchos sitios bloquean el embebido con
   X-Frame-Options y quedaria un cuadro negro vacio). */
function videoEmbedURL(url){
  const u = String(url || '').trim();
  if(!u) return null;
  let m;

  /* --- YouTube: watch?v= | youtu.be | /shorts/ | /embed/ | /live/ | /v/ --- */
  m = u.match(/(?:youtube\.com\/(?:watch\?(?:[^#]*&)?v=|embed\/|shorts\/|live\/|v\/)|youtu\.be\/)([A-Za-z0-9_-]{6,20})/);
  if(m){
    /* arranque en segundo N: soporta ?t=90 y ?start=90 (el formato 1m30s no) */
    const t = (u.match(/[?&](?:t|start)=(\d+)/) || [])[1];
    return {
      tipo: 'youtube',
      src: 'https://www.youtube-nocookie.com/embed/' + m[1]
         + '?rel=0&modestbranding=1&playsinline=1' + (t ? '&start=' + t : ''),
      /* un Short es siempre 9:16 */
      vert: /\/shorts\//.test(u)
    };
  }

  /* --- Vimeo: vimeo.com/ID | vimeo.com/ID/HASH (no listado) | player.vimeo.com/video/ID --- */
  m = u.match(/vimeo\.com\/(?:video\/)?(\d{6,12})(?:[\/?#]([A-Za-z0-9]{6,20}))?/);
  if(m){
    return {
      tipo: 'vimeo',
      /* el hash h= es obligatorio si el video es "no listado" */
      src: 'https://player.vimeo.com/video/' + m[1] + (m[2] ? '?h=' + m[2] : ''),
      vert: false
    };
  }

  /* --- Google Drive: /file/d/ID/view | open?id=ID | uc?id=ID  ->  /preview --- */
  m = u.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?(?:[^#]*&)?id=)([A-Za-z0-9_-]{20,60})/);
  if(m){
    return {
      tipo: 'drive',
      src: 'https://drive.google.com/file/d/' + m[1] + '/preview',
      vert: false
    };
  }

  return null;
}

